using SB.BACKEND.Domain.Support;
using Xunit;
namespace SB.BACKEND.Tests;
public sealed class SupportDomainTests
{
    private static SolicitudSoporte Request() => new("SOL-2026-000001","Acceso","Descripción",TipoSolicitud.Soporte,PrioridadSolicitud.Media,Guid.NewGuid(),Guid.NewGuid(),null,DateTimeOffset.UtcNow.AddDays(1));
    [Fact] public void New_request_starts_registered_and_active(){var value=Request();Assert.Equal(EstadoSolicitud.Registrada,value.Estado);Assert.True(value.IsActive);Assert.False(value.IsDeleted);}
    [Fact] public void Valid_transition_creates_history(){var value=Request();value.CambiarEstado(EstadoSolicitud.EnAnalisis,"Analizando",Guid.NewGuid(),DateTimeOffset.UtcNow);Assert.Equal(EstadoSolicitud.EnAnalisis,value.Estado);Assert.Single(value.Historial);}
    [Fact] public void Invalid_transition_is_rejected(){var value=Request();Assert.Throws<InvalidOperationException>(()=>value.CambiarEstado(EstadoSolicitud.Resuelta,"Listo",Guid.NewGuid(),DateTimeOffset.UtcNow));}
    [Fact] public void Resolution_records_utc_date(){var value=Request();var user=Guid.NewGuid();value.CambiarEstado(EstadoSolicitud.EnAnalisis,"Análisis",user,DateTimeOffset.UtcNow);value.CambiarEstado(EstadoSolicitud.EnProgreso,"Inicio",user,DateTimeOffset.UtcNow);value.RegistrarResolucion("Resuelto");value.CambiarEstado(EstadoSolicitud.Resuelta,"Solución",user,DateTimeOffset.Now);Assert.NotNull(value.FechaResolucion);Assert.Equal(TimeSpan.Zero,value.FechaResolucion!.Value.Offset);}
    [Fact] public void Closing_without_resolution_is_rejected(){var value=Request();var user=Guid.NewGuid();value.CambiarEstado(EstadoSolicitud.EnAnalisis,"Análisis",user,DateTimeOffset.UtcNow);value.CambiarEstado(EstadoSolicitud.EnProgreso,"Inicio",user,DateTimeOffset.UtcNow);value.RegistrarResolucion("Resuelto");value.CambiarEstado(EstadoSolicitud.Resuelta,"Solución",user,DateTimeOffset.UtcNow);var second=Request();Assert.Throws<InvalidOperationException>(()=>second.CambiarEstado(EstadoSolicitud.Cerrada,"Cierre",user,DateTimeOffset.UtcNow));}
    [Fact] public void Reopen_closed_request_returns_to_progress(){var value=Request();var user=Guid.NewGuid();value.CambiarEstado(EstadoSolicitud.EnAnalisis,"Análisis",user,DateTimeOffset.UtcNow);value.CambiarEstado(EstadoSolicitud.EnProgreso,"Inicio",user,DateTimeOffset.UtcNow);value.RegistrarResolucion("Resuelto");value.CambiarEstado(EstadoSolicitud.Resuelta,"Solución",user,DateTimeOffset.UtcNow);value.CambiarEstado(EstadoSolicitud.Cerrada,"Cierre",user,DateTimeOffset.UtcNow);value.Reabrir("Reincidencia",user,DateTimeOffset.UtcNow);Assert.Equal(EstadoSolicitud.EnProgreso,value.Estado);Assert.Null(value.FechaCierre);}
    [Fact] public void Soft_delete_marks_request_inactive(){var value=Request();value.Eliminar(DateTimeOffset.Now,Guid.NewGuid());Assert.True(value.IsDeleted);Assert.False(value.IsActive);Assert.Equal(TimeSpan.Zero,value.DeletedAt!.Value.Offset);}
    [Fact] public void Assignment_preserves_previous_responsible(){var value=Request();var first=Guid.NewGuid();var second=Guid.NewGuid();var actor=Guid.NewGuid();Assert.Null(value.Asignar(first,actor,DateTimeOffset.UtcNow));Assert.Equal(first,value.Asignar(second,actor,DateTimeOffset.UtcNow));Assert.Equal(second,value.ResponsableId);Assert.Equal(2,value.Historial.Count);}
    [Fact] public void Internal_comment_is_identified(){var value=new ComentarioSolicitud(Guid.NewGuid(),Guid.NewGuid(),"Diagnóstico",true);Assert.True(value.EsInterno);Assert.Equal("Diagnóstico",value.Contenido);}
    [Fact] public void Notification_can_be_marked_read_in_utc(){var value=new Notificacion(Guid.NewGuid(),Guid.NewGuid(),TipoNotificacion.Asignacion,"Asignación","Mensaje");value.MarcarLeida(DateTimeOffset.Now);Assert.True(value.Leida);Assert.Equal(TimeSpan.Zero,value.FechaLectura!.Value.Offset);}
    [Fact] public void Area_soft_delete_uses_audit_state(){var value=new Area("Tecnología","TECNOLOGÍA",null);value.Eliminar(DateTimeOffset.Now,Guid.NewGuid());Assert.True(value.IsDeleted);Assert.False(value.IsActive);}
}
